  "type": "module",
  "license": "MIT",
  "author": "KelpHect",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/KelpHect/opencode-orchestrator.git"
  },
  "homepage": "https://github.com/KelpHect/opencode-orchestrator#readme",
  "bugs": {
    "url": "https://github.com/KelpHect/opencode-orchestrator/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "subagents",
    "orchestration",
    "skills"
  ],
  "main": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "src",
    "skills",
    "examples",
    "AGENTS.md",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.30",
    "@types/bun": "1.4.3",
    "typescript": "5.9.3"
  }
}
